```php
class ImportCsv extends Command {
    protected $signature = 'import:csv {fail} {--chunk=500}';
    public function handle(): int {
        $fail = $this->argument('fail');
        if (! file_exists($fail)) { $this->error('Tiada fail.'); return self::FAILURE; }
        $this->withProgressBar(collect(file($fail)), fn ($b) => ImportBaris::dispatch($b));
        $this->info('Siap.');
        return self::SUCCESS;
    }
}
// ujian:
it('gagal tanpa fail', fn () => $this->artisan('import:csv tiada.csv')->assertFailed());
```
Sahkan input (fail wujud!), bar kemajuan untuk pukal, kod keluar kontrak, ujian panggil artisan terus (bukan shell). Queue per baris untuk fail besar.

